// Given
  type enumerated EWeekDays {
     Mon, Tue, Wed, Thu, Fri, Sat, Sun
  };
  type enumerated EWorkDays {
     Mon, Tue, Wed, Thu, Fri
  };
  type enumerated EDesWeekDays {
     Tue, Wed, Thu, Fri, Sat, Sun, Mon
  };
  type enumerated EComplexValues {
   e_num (1),
   e_expr (2+2),
   e_bin_conv (bit2int('0111'B)),
   e_oct_conv (oct2int('34'O)),
   e_hex_conv (hex2int('AC'H))
  }
  type enumerated ESimpleValues {
   e_num (1),
   e_expr (4),
   e_bin_conv (7),
   e_oct_conv (52),
   e_hex_conv (172)
  }
  var EWeekDays v_myWeekDayMon := Mon
  var EWeekDays v_myWeekDaySun := Sun
  var EWorkDays v_myWorkDayMon := Mon
  var EDesWeekDays v_myDesWeekDayMon := Mon
  var EComplexValues v_myComplexValuedEnum := e_bin_conv;
  var ESimpleValues v_mySimpleValuedEnum := e_bin_conv;
  v_myWorkDayMon := v_myWeekDayMon
     // works
  v_mySimpleValuedEnum := v_myComplexValuedEnum;
     // works
  v_myWorkDayMon := v_myWeekDaySun
     // causes an error as Sun is not a member of EWorkDays
  v_myDesWeekDayMon := v_myWeekDayMon
     // causes an error as Mon in EDesWeekDays and EWeekDays have different associated 
     // numbers; since this is true for all enumerated values in EWeekDays, these two 
     // types are fully incompatible

